import{E as e}from"./chunks/EscalaBristol.27cf8c5d.js";import{_ as t,o,c as s,H as d,Q as a}from"./chunks/framework.77ba20c6.js";const r=a('<h1 id="🎒-la-mochila-del-paciente" tabindex="-1" data-v-fcd73e29>🎒 La Mochila del Paciente <a class="header-anchor" href="#🎒-la-mochila-del-paciente" aria-label="Permalink to &quot;🎒 La Mochila del Paciente&quot;" data-v-fcd73e29>​</a></h1><p data-v-fcd73e29>Todo lo que necesitas para llegar a la consulta con argumentos y no con disculpas.</p><h2 id="📄-calendario-de-sintomas-pdf-imprimible" tabindex="-1" data-v-fcd73e29>📄 Calendario de síntomas (PDF imprimible) <a class="header-anchor" href="#📄-calendario-de-sintomas-pdf-imprimible" aria-label="Permalink to &quot;📄 Calendario de síntomas (PDF imprimible)&quot;" data-v-fcd73e29>​</a></h2><p data-v-fcd73e29><strong data-v-fcd73e29>Lo que es:</strong> un PDF mensual con tu encabezado, el subtítulo <em data-v-fcd73e29>&quot;Calendario de síntomas — Registro diario&quot;</em>, una tabla de 31 días con 6 columnas (fecha, deposiciones, dolor 1-10, estrés 1-10, sueño en horas, notas) y, en la segunda página, la <strong data-v-fcd73e29>Escala de Bristol</strong> como referencia. Todo con la paleta de tu web.</p><p data-v-fcd73e29><strong data-v-fcd73e29>Cómo generarlo:</strong> entra en <a href="/tablero#generar-pdf-para-imprimir" data-v-fcd73e29>Mi Tablero → Generar PDF</a>, elige el mes y descárgalo. También se autocompleta con los registros que ya tengas.</p><div class="cta-box" data-v-fcd73e29><a class="btn-cta" href="/tablero#generar-pdf-para-imprimir" data-v-fcd73e29>📥 Ir al generador de PDF</a></div><h2 id="🚽-escala-de-bristol" tabindex="-1" data-v-fcd73e29>🚽 Escala de Bristol <a class="header-anchor" href="#🚽-escala-de-bristol" aria-label="Permalink to &quot;🚽 Escala de Bristol&quot;" data-v-fcd73e29>​</a></h2>',7),i=a('<h2 id="📋-preguntas-para-tu-medico" tabindex="-1" data-v-fcd73e29>📋 Preguntas para tu médico <a class="header-anchor" href="#📋-preguntas-para-tu-medico" aria-label="Permalink to &quot;📋 Preguntas para tu médico&quot;" data-v-fcd73e29>​</a></h2><p data-v-fcd73e29>Antes de tu próxima consulta, revisa estas preguntas. Anota las respuestas y lleva tus registros impresos (el PDF de arriba sirve).</p><ul data-v-fcd73e29><li data-v-fcd73e29>¿Cómo está mi inflamación según los últimos análisis (calprotectina, PCR)?</li><li data-v-fcd73e29>¿Debería ajustar la medicación si noto un patrón de empeoramiento en X días?</li><li data-v-fcd73e29>¿Hay señales de alarma por las que debería llamar antes de la próxima cita?</li><li data-v-fcd73e29>¿Es buen momento para hablar de nuevos tratamientos/biológicos?</li><li data-v-fcd73e29>¿Necesito alguna prueba adicional (colonoscopia, resonancia, cápsula endoscópica)?</li></ul><h2 id="🧠-guia-de-afrontamiento-emocional" tabindex="-1" data-v-fcd73e29>🧠 Guía de afrontamiento emocional <a class="header-anchor" href="#🧠-guia-de-afrontamiento-emocional" aria-label="Permalink to &quot;🧠 Guía de afrontamiento emocional&quot;" data-v-fcd73e29>​</a></h2><ul data-v-fcd73e29><li data-v-fcd73e29><strong data-v-fcd73e29>Permítete no estar bien.</strong> La EII no se &quot;cura con voluntad&quot;. No eres tu intestino.</li><li data-v-fcd73e29><strong data-v-fcd73e29>Lleva registro, no sólo memoria.</strong> Los días malos se olvidan. Los datos, no.</li><li data-v-fcd73e29><strong data-v-fcd73e29>Comunica con datos.</strong> &quot;He tenido dolor &gt;7/10 cuatro días esta semana&quot; funciona mejor que &quot;creo que estoy peor&quot;.</li><li data-v-fcd73e29><strong data-v-fcd73e29>Ten un plan B para días malos.</strong> Dónde estás, a quién llamas, qué medicación de rescate tienes pautada.</li><li data-v-fcd73e29><strong data-v-fcd73e29>Cuida a tu equipo.</strong> Tu médico, tu familia, tus amigos. No van a saber qué necesitas si no se lo dices.</li></ul><h2 id="🌐-descarga-mas-recursos-en-eii-web-pages-dev" tabindex="-1" data-v-fcd73e29>🌐 Descarga más recursos en <a href="https://eii-web.pages.dev" target="_blank" rel="noreferrer" data-v-fcd73e29>eii-web.pages.dev</a> <a class="header-anchor" href="#🌐-descarga-mas-recursos-en-eii-web-pages-dev" aria-label="Permalink to &quot;🌐 Descarga más recursos en [eii-web.pages.dev](https://eii-web.pages.dev)&quot;" data-v-fcd73e29>​</a></h2><p data-v-fcd73e29>Toda la web, las actualizaciones y futuros materiales viven aquí.</p>',7),v=JSON.parse('{"title":"Recursos","description":"","frontmatter":{"title":"Recursos"},"headers":[],"relativePath":"recursos.md","filePath":"recursos.md"}'),n={name:"recursos.md"},c=Object.assign(n,{setup(l){return(u,m)=>(o(),s("div",null,[r,d(e),i]))}}),g=t(c,[["__scopeId","data-v-fcd73e29"]]);export{v as __pageData,g as default};
